function getNotionAiTranslation(key, lang) {
    if (notionAiTranslations[lang] && notionAiTranslations[lang][key]) {
        return notionAiTranslations[lang][key];
    }
    if (notionAiTranslations.en && notionAiTranslations.en[key]) {
        return notionAiTranslations.en[key];
    }
    return null;
}

function applyNotionAiTranslations(lang) {
    console.log('Applying notion-ai translations for:', lang);
    let count = 0;
    document.querySelectorAll('[data-i18n]').forEach(element => {
        const key = element.getAttribute('data-i18n');
        if (key && (key.startsWith('review.notion-ai.') || key.startsWith('review.common.') || key.startsWith('nav.'))) {
            const translation = getNotionAiTranslation(key, lang);
            if (translation) {
                element.textContent = translation;
                count++;
            }
        }
    });
    console.log('Applied ' + count + ' notion-ai translations');
}

document.addEventListener('languageChanged', (e) => {
    const lang = e.detail.language;
    setTimeout(() => applyNotionAiTranslations(lang), 200);
});

if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', () => {
        const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
        applyNotionAiTranslations(currentLang);
    });
} else {
    const currentLang = window.i18n ? window.i18n.getCurrentLanguage() : 'en';
    applyNotionAiTranslations(currentLang);
}

console.log('notion-ai i18n loaded');
